insert into scriptura_app_units (id,language_id,title,subtitle,accent,sort,slots,concept) values ('burmese_misc','burmese','Miscellaneous','အမျိုးမျိုး','cjk',5,NULL,'{"id":"burmese-stacking","glyph":"န္တ","title":"Letters that stack","blurb":"In some words — mostly from Pali and Sanskrit — one consonant is tucked underneath another instead of being written after it.","note":"Read once before the last consonant group","positions":[{"id":"nta","tab":"န + တ","sound":"n · d","ipa":"","rule":"The top letter closes the syllable before it (as if it had ်); the bottom one starts the next.","parts":[{"t":"မ"},{"t":"န္တ","hi":1},{"t":"လေး"}],"roman":[{"t":"ma"},{"t":"nda","hi":1},{"t":"lay"}],"mean":"Mandalay"},{"id":"dda","tab":"ဒ + ဓ","sound":"k · d","ipa":"","rule":"Stacks usually pair letters from the same row of the grid — here both are dentals. The top one closes as a stop.","parts":[{"t":"ဗု"},{"t":"ဒ္ဓ","hi":1}],"roman":[{"t":"bou"},{"t":"k-da","hi":1}],"mean":"Buddha"},{"id":"ssa","tab":"စ + စ","sound":"t · s","ipa":"","rule":"A letter can also stack on itself: the top copy closes the syllable, the bottom one opens the next.","parts":[{"t":"ပ"},{"t":"စ္စ","hi":1},{"t":"ည်း"}],"roman":[{"t":"pyi"},{"t":"t-s","hi":1},{"t":"i"}],"mean":"thing, belongings"}],"contrast":{"from":{"text":"န် + တ","font":"var(--font-burmese)","label":"written in a row"},"to":{"text":"န္တ","label":"stacked"},"note":"Same sounds either way — stacking drops the ် and moves the second letter underneath. Read top, then bottom."}}'::jsonb);
