insert into scriptura_app_languages (id,name,native,grp,font,sort) values ('tamil','Tamil','தமிழ்','South Asian','var(--font-tamil)',4) on conflict (id) do update set name=excluded.name, native=excluded.native, grp=excluded.grp, font=excluded.font, sort=excluded.sort;
insert into scriptura_app_units (id,language_id,title,subtitle,accent,sort,slots,concept) values ('tamil_uyir','tamil','Uyir','Vowels · உயிர்','practice',0,NULL,NULL);
insert into scriptura_app_units (id,language_id,title,subtitle,accent,sort,slots,concept) values ('tamil_ka','tamil','Ka group','Velar · க ங','quiz',1,'[0,null,null,null,1]'::jsonb,'{"id":"tamil-ka-allophony","title":"One letter, two sounds","blurb":"Tamil doesn’t spell the difference between k and g — where the letter sits in the word decides it.","note":"Read once before the Ka group","glyph":"க","positions":[{"id":"initial","tab":"Start of word","sound":"k","ipa":"/k/","rule":"Word-initial க is always a hard k.","parts":[{"t":"க","hi":1},{"t":"டல்"}],"roman":[{"t":"ka","hi":1},{"t":"dal"}],"mean":"sea"},{"id":"double","tab":"Doubled","sound":"k","ipa":"/k/","rule":"Doubled க்க stays hard — this is how Tamil writes a real k between vowels.","parts":[{"t":"ப"},{"t":"க்க","hi":1},{"t":"ம்"}],"roman":[{"t":"pa"},{"t":"kka","hi":1},{"t":"m"}],"mean":"page, side"},{"id":"medial","tab":"Between vowels","sound":"g","ipa":"/ɣ~g/","rule":"A single க between two vowels softens to g — in some words closer to h.","parts":[{"t":"ம"},{"t":"க","hi":1},{"t":"ன்"}],"roman":[{"t":"ma"},{"t":"ga","hi":1},{"t":"n"}],"mean":"son"},{"id":"nasal","tab":"After ங","sound":"g","ipa":"/ŋg/","rule":"After its own nasal ங, க voices to g.","parts":[{"t":"தங்"},{"t":"க","hi":1},{"t":"ம்"}],"roman":[{"t":"tha"},{"t":"nga","hi":1},{"t":"m"}],"mean":"gold"}],"contrast":{"from":{"text":"क ख ग घ","font":"var(--font-devanagari)","label":"Hindi · 4 letters"},"to":{"text":"க","label":"Tamil · 1 letter"},"note":"Tamil has no aspirates and no separate voiced stops, so there was never a kha or gha to spell. The same holds for ச · ட · த · ப."}}'::jsonb);
insert into scriptura_app_units (id,language_id,title,subtitle,accent,sort,slots,concept) values ('tamil_ca','tamil','Ca group','Palatal · ச ஞ','sheet',2,'[0,null,null,null,1]'::jsonb,'{"id":"tamil-ca-allophony","glyph":"ச","title":"ச — one letter, two sounds","blurb":"Same rule as க: where ச sits in the word decides whether it is ch or s / j.","note":"Read once before the Ca group","positions":[{"id":"initial","tab":"Start of word","sound":"s","ipa":"/s~tʃ/","rule":"Word-initial ச is usually s in speech (ch in careful reading).","parts":[{"t":"ச","hi":1},{"t":"ட்டை"}],"roman":[{"t":"sa","hi":1},{"t":"ṭṭai"}],"mean":"shirt"},{"id":"double","tab":"Doubled","sound":"ch","ipa":"/ttʃ/","rule":"Doubled ச்ச is always a hard ch.","parts":[{"t":"ப"},{"t":"ச்சை","hi":1}],"roman":[{"t":"pa"},{"t":"cc","hi":1},{"t":"ai"}],"mean":"green"},{"id":"medial","tab":"Between vowels","sound":"s","ipa":"/s/","rule":"A single ச between vowels is s.","parts":[{"t":"ப"},{"t":"சு","hi":1}],"roman":[{"t":"pa"},{"t":"su","hi":1}],"mean":"cow"},{"id":"nasal","tab":"After ஞ","sound":"j","ipa":"/ɲdʒ/","rule":"After its own nasal ஞ, ச voices to j.","parts":[{"t":"பஞ்"},{"t":"சு","hi":1}],"roman":[{"t":"pañ"},{"t":"ju","hi":1}],"mean":"cotton"}],"contrast":{"from":{"text":"च छ ज झ","font":"var(--font-devanagari)","label":"Hindi · 4 letters"},"to":{"text":"ச","label":"Tamil · 1 letter"},"note":"No aspirates, no separate voiced letter — one ச covers all four Hindi sounds."}}'::jsonb);
insert into scriptura_app_units (id,language_id,title,subtitle,accent,sort,slots,concept) values ('tamil_tta','tamil','Ta group','Retroflex · ட ண','review',3,'[0,null,null,null,1]'::jsonb,'{"id":"tamil-tta-allophony","glyph":"ட","title":"ட — one letter, two sounds","blurb":"Same rule as க: where ட sits in the word decides whether it is ṭ or ḍ.","note":"Read once before the retroflex Ta group","positions":[{"id":"initial","tab":"Start of word","sound":"ṭ","ipa":"/ʈ/","rule":"Native Tamil words never start with ட — you only see it first in loanwords.","parts":[{"t":"ட","hi":1},{"t":"ம்ளர்"}],"roman":[{"t":"ṭa","hi":1},{"t":"mḷar"}],"mean":"tumbler (loanword)"},{"id":"double","tab":"Doubled","sound":"ṭṭ","ipa":"/ʈʈ/","rule":"Doubled ட்ட stays hard.","parts":[{"t":"ப"},{"t":"ட்ட","hi":1},{"t":"ம்"}],"roman":[{"t":"pa"},{"t":"ṭṭa","hi":1},{"t":"m"}],"mean":"kite; title"},{"id":"medial","tab":"Between vowels","sound":"ḍ","ipa":"/ɖ~ɽ/","rule":"A single ட between vowels softens to ḍ, often a quick flap.","parts":[{"t":"வீ"},{"t":"டு","hi":1}],"roman":[{"t":"vī"},{"t":"ḍu","hi":1}],"mean":"house"},{"id":"nasal","tab":"After ண","sound":"ḍ","ipa":"/ɳɖ/","rule":"After its own nasal ண, ட voices to ḍ.","parts":[{"t":"வண்"},{"t":"டி","hi":1}],"roman":[{"t":"vaṇ"},{"t":"ḍi","hi":1}],"mean":"cart"}],"contrast":{"from":{"text":"ट ठ ड ढ","font":"var(--font-devanagari)","label":"Hindi · 4 letters"},"to":{"text":"ட","label":"Tamil · 1 letter"},"note":"Tongue curled back for all of them — Tamil just doesn’t spell voicing."}}'::jsonb);
insert into scriptura_app_units (id,language_id,title,subtitle,accent,sort,slots,concept) values ('tamil_ta','tamil','Ta group','Dental · த ந','indic',4,'[0,null,null,null,1]'::jsonb,'{"id":"tamil-ta-allophony","glyph":"த","title":"த — one letter, two sounds","blurb":"Same rule as க: where த sits in the word decides whether it is t or d.","note":"Read once before the dental Ta group","positions":[{"id":"initial","tab":"Start of word","sound":"t","ipa":"/t̪/","rule":"Word-initial த is a hard dental t — tongue on the teeth.","parts":[{"t":"த","hi":1},{"t":"மிழ்"}],"roman":[{"t":"ta","hi":1},{"t":"miḻ"}],"mean":"Tamil"},{"id":"double","tab":"Doubled","sound":"tt","ipa":"/t̪t̪/","rule":"Doubled த்த stays hard.","parts":[{"t":"ப"},{"t":"த்து","hi":1}],"roman":[{"t":"pa"},{"t":"ttu","hi":1}],"mean":"ten"},{"id":"medial","tab":"Between vowels","sound":"d","ipa":"/d̪~ð/","rule":"A single த between vowels softens to d, close to the th in “this”.","parts":[{"t":"பா"},{"t":"த","hi":1},{"t":"ம்"}],"roman":[{"t":"pā"},{"t":"da","hi":1},{"t":"m"}],"mean":"foot"},{"id":"nasal","tab":"After ந","sound":"d","ipa":"/n̪d̪/","rule":"After its own nasal ந, த voices to d.","parts":[{"t":"பந்"},{"t":"து","hi":1}],"roman":[{"t":"pan"},{"t":"du","hi":1}],"mean":"ball"}],"contrast":{"from":{"text":"त थ द ध","font":"var(--font-devanagari)","label":"Hindi · 4 letters"},"to":{"text":"த","label":"Tamil · 1 letter"},"note":"Keep it dental: த is a different letter from the retroflex ட you just learned."}}'::jsonb);
insert into scriptura_app_units (id,language_id,title,subtitle,accent,sort,slots,concept) values ('tamil_pa','tamil','Pa group','Labial · ப ம','cjk',5,'[0,null,null,null,1]'::jsonb,'{"id":"tamil-pa-allophony","glyph":"ப","title":"ப — one letter, two sounds","blurb":"Same rule as க: where ப sits in the word decides whether it is p or b.","note":"Read once before the Pa group","positions":[{"id":"initial","tab":"Start of word","sound":"p","ipa":"/p/","rule":"Word-initial ப is a hard p.","parts":[{"t":"ப","hi":1},{"t":"ல்"}],"roman":[{"t":"pa","hi":1},{"t":"l"}],"mean":"tooth"},{"id":"double","tab":"Doubled","sound":"pp","ipa":"/pp/","rule":"Doubled ப்ப stays hard.","parts":[{"t":"அ"},{"t":"ப்பா","hi":1}],"roman":[{"t":"a"},{"t":"ppā","hi":1}],"mean":"father"},{"id":"medial","tab":"Between vowels","sound":"b","ipa":"/b~β/","rule":"A single ப between vowels softens to b, lips barely touching.","parts":[{"t":"கோ"},{"t":"ப","hi":1},{"t":"ம்"}],"roman":[{"t":"kō"},{"t":"ba","hi":1},{"t":"m"}],"mean":"anger"},{"id":"nasal","tab":"After ம","sound":"b","ipa":"/mb/","rule":"After its own nasal ம, ப voices to b.","parts":[{"t":"பாம்"},{"t":"பு","hi":1}],"roman":[{"t":"pām"},{"t":"bu","hi":1}],"mean":"snake"}],"contrast":{"from":{"text":"प फ ब भ","font":"var(--font-devanagari)","label":"Hindi · 4 letters"},"to":{"text":"ப","label":"Tamil · 1 letter"},"note":"That completes the pattern: க ச ட த ப each stand for a hard and a soft sound."}}'::jsonb);
