insert into scriptura_app_units (id,language_id,title,subtitle,accent,sort,slots,concept) values ('hiragana_k','hiragana','K-row','か','quiz',1,NULL,'{"id":"hiragana-dakuten","glyph":"が","title":"Two small marks, a new sound","blurb":"A tiny ゛ (dakuten) voices the consonant; a tiny ゜ (handakuten), only on the H-row, turns it into p. No new shapes to learn.","note":"Read once before the K-row","positions":[{"id":"g","tab":"か → が","sound":"g","ipa":"/ɡ/","rule":"゛ turns k into g.","parts":[{"t":"が","hi":1},{"t":"っこう"}],"roman":[{"t":"ga","hi":1},{"t":"kkō"}],"mean":"school"},{"id":"z","tab":"さ → ざ","sound":"z","ipa":"/z/","rule":"゛ turns s into z.","parts":[{"t":"ざ","hi":1},{"t":"っし"}],"roman":[{"t":"za","hi":1},{"t":"sshi"}],"mean":"magazine"},{"id":"d","tab":"た → だ","sound":"d","ipa":"/d/","rule":"゛ turns t into d.","parts":[{"t":"だ","hi":1},{"t":"いがく"}],"roman":[{"t":"da","hi":1},{"t":"igaku"}],"mean":"university"},{"id":"b","tab":"は → ば","sound":"b","ipa":"/b/","rule":"゛ on the H-row gives b, not v.","parts":[{"t":"ば","hi":1},{"t":"んごはん"}],"roman":[{"t":"ba","hi":1},{"t":"ngohan"}],"mean":"dinner"},{"id":"p","tab":"は → ぱ","sound":"p","ipa":"/p/","rule":"゜ — the small circle — only goes on the H-row, and gives p.","parts":[{"t":"ぱ","hi":1},{"t":"ん"}],"roman":[{"t":"pa","hi":1},{"t":"n"}],"mean":"bread"}],"contrast":{"from":{"text":"か さ た は","font":"var(--font-japanese)","label":"plain"},"to":{"text":"が ざ だ ば ぱ","label":"marked"},"note":"Five rows you already know give you 25 more sounds for free."}}'::jsonb);
