insert into scriptura_app_units (id,language_id,title,subtitle,accent,sort,slots,concept) values ('katakana_k','katakana','K-row','カ','quiz',1,NULL,'{"id":"katakana-dakuten","glyph":"ガ","title":"Two small marks, a new sound","blurb":"A tiny ゛ (dakuten) voices the consonant; a tiny ゜ (handakuten), only on the H-row, turns it into p. No new shapes to learn.","note":"Read once before the K-row","positions":[{"id":"g","tab":"カ → ガ","sound":"g","ipa":"/ɡ/","rule":"゛ turns k into g.","parts":[{"t":"ガ","hi":1},{"t":"ム"}],"roman":[{"t":"ga","hi":1},{"t":"mu"}],"mean":"chewing gum"},{"id":"z","tab":"サ → ザ","sound":"z","ipa":"/z/","rule":"゛ turns s into z.","parts":[{"t":"ゼ","hi":1},{"t":"ロ"}],"roman":[{"t":"ze","hi":1},{"t":"ro"}],"mean":"zero"},{"id":"d","tab":"タ → ダ","sound":"d","ipa":"/d/","rule":"゛ turns t into d.","parts":[{"t":"ド","hi":1},{"t":"ア"}],"roman":[{"t":"do","hi":1},{"t":"a"}],"mean":"door"},{"id":"b","tab":"ハ → バ","sound":"b","ipa":"/b/","rule":"゛ on the H-row gives b, not v.","parts":[{"t":"バ","hi":1},{"t":"ス"}],"roman":[{"t":"ba","hi":1},{"t":"su"}],"mean":"bus"},{"id":"p","tab":"ハ → パ","sound":"p","ipa":"/p/","rule":"゜ — the small circle — only goes on the H-row, and gives p.","parts":[{"t":"パ","hi":1},{"t":"ン"}],"roman":[{"t":"pa","hi":1},{"t":"n"}],"mean":"bread"}],"contrast":{"from":{"text":"カ サ タ ハ","font":"var(--font-japanese)","label":"plain"},"to":{"text":"ガ ザ ダ バ パ","label":"marked"},"note":"Five rows you already know give you 25 more sounds for free."}}'::jsonb);
