-- ============================================================
-- Scriptura — full catalogue resync, generated from ui_kits/scriptura/data.js
-- Run once in Supabase → SQL editor. Safe to re-run (idempotent).
--
-- Replaces the content rows (languages / units / characters / vowels) for
-- every language with exactly what the app ships:
--   • Tamil in Hindi-grid order (Ka · Ca · Ṭa · Ta · Pa · Ra groups + Grantha)
--   • Sinhala and the full Hindi chart
--   • unit.slots   — grid positions for honest gaps on the practice sheet
--   • unit.concept — read-once concept cards (Tamil, Burmese stacking, kana dakuten)
--   • no_vowel_sign — letters the Word Builder must skip
-- Progress (scriptura_app_sheet_stats) is keyed by language + char_index and
-- is NOT touched.
-- Supersedes scriptura_app_fix_tamil_hindi.sql and scriptura_app_add_sinhala.sql.
-- ============================================================

begin;

alter table scriptura_app_units      add column if not exists slots   jsonb;
alter table scriptura_app_units      add column if not exists concept jsonb;
alter table scriptura_app_characters add column if not exists no_vowel_sign boolean default false;

-- ---------- Burmese (33 characters, 6 units) ----------
delete from scriptura_app_characters where language_id='burmese';
delete from scriptura_app_vowels where language_id='burmese';
delete from scriptura_app_units where language_id='burmese';

-- ---------- Hindi (36 characters, 6 units) ----------
delete from scriptura_app_characters where language_id='hindi';
delete from scriptura_app_vowels where language_id='hindi';
delete from scriptura_app_units where language_id='hindi';

-- ---------- Telugu (35 characters, 6 units) ----------
delete from scriptura_app_characters where language_id='telugu';
delete from scriptura_app_vowels where language_id='telugu';
delete from scriptura_app_units where language_id='telugu';

-- ---------- Sinhala (35 characters, 6 units) ----------
delete from scriptura_app_characters where language_id='sinhala';
delete from scriptura_app_vowels where language_id='sinhala';
delete from scriptura_app_units where language_id='sinhala';

-- ---------- Tamil (37 characters, 9 units) ----------
delete from scriptura_app_characters where language_id='tamil';
delete from scriptura_app_vowels where language_id='tamil';
delete from scriptura_app_units where language_id='tamil';

-- ---------- Hiragana (46 characters, 10 units) ----------
delete from scriptura_app_characters where language_id='hiragana';
delete from scriptura_app_vowels where language_id='hiragana';
delete from scriptura_app_units where language_id='hiragana';

-- ---------- Katakana (46 characters, 10 units) ----------
delete from scriptura_app_characters where language_id='katakana';
delete from scriptura_app_vowels where language_id='katakana';
delete from scriptura_app_units where language_id='katakana';

-- ---------- Korean (19 characters, 3 units) ----------
delete from scriptura_app_characters where language_id='korean';
delete from scriptura_app_vowels where language_id='korean';
delete from scriptura_app_units where language_id='korean';

-- ---------- Chinese (20 characters, 2 units) ----------
delete from scriptura_app_characters where language_id='chinese';
delete from scriptura_app_vowels where language_id='chinese';
delete from scriptura_app_units where language_id='chinese';

commit;
